ALTER TABLE public.club_bar_settings ADD COLUMN staff_normal_opening time NOT NULL DEFAULT '16:00';
ALTER TABLE public.bar_staff_salaries ADD COLUMN hourly_rate numeric(12,2) NOT NULL DEFAULT 0 CHECK(hourly_rate>=0);
ALTER TABLE public.bar_staff_salaries DROP CONSTRAINT bar_staff_salaries_pay_basis_check;
ALTER TABLE public.bar_staff_salaries ADD CONSTRAINT bar_staff_salaries_pay_basis_check CHECK(pay_basis IN ('monthly','shift','hourly'));
ALTER TABLE public.bar_payroll_run_lines DROP CONSTRAINT bar_payroll_run_lines_pay_basis_check;
ALTER TABLE public.bar_payroll_run_lines ADD CONSTRAINT bar_payroll_run_lines_pay_basis_check CHECK(pay_basis IN ('monthly','shift','hourly'));
ALTER TABLE public.bar_payroll_run_lines ADD COLUMN hours numeric;
ALTER TABLE public.bar_payroll_run_lines ADD COLUMN hourly_rate numeric(12,2);
ALTER TABLE public.bar_payroll_runs ADD COLUMN attendance_cutoff timestamptz;
CREATE TABLE public.bar_work_shifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES public.clubs(id),kind text NOT NULL CHECK(kind IN ('normal','special')),split_tips boolean NOT NULL DEFAULT false,opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz, CHECK(NOT split_tips OR kind='special'));
GRANT SELECT ON public.bar_work_shifts TO authenticated; GRANT ALL ON public.bar_work_shifts TO service_role;
ALTER TABLE public.bar_work_shifts ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_shift_read ON public.bar_work_shifts FOR SELECT TO authenticated USING(public.is_club_admin_or_permitted(auth.uid(),club_id,'bar') OR public.has_club_permission(auth.uid(),club_id,'finance') OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX bar_work_shift_one_open ON public.bar_work_shifts(club_id) WHERE closed_at IS NULL;
CREATE TABLE public.bar_staff_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES public.clubs(id),shift_id uuid NOT NULL REFERENCES public.bar_work_shifts(id),staff_id uuid NOT NULL REFERENCES public.bar_counter_devices(id),session_id uuid NOT NULL REFERENCES public.bar_counter_sessions(id),entered_at timestamptz NOT NULL DEFAULT now(),paid_start timestamptz NOT NULL,ended_at timestamptz,end_reason text,correction_reason text,corrected_by uuid,corrections jsonb NOT NULL DEFAULT '[]'::jsonb);
GRANT SELECT ON public.bar_staff_attendance TO authenticated; GRANT ALL ON public.bar_staff_attendance TO service_role;
ALTER TABLE public.bar_staff_attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_attendance_read ON public.bar_staff_attendance FOR SELECT TO authenticated USING(public.is_club_admin_or_permitted(auth.uid(),club_id,'bar') OR public.has_club_permission(auth.uid(),club_id,'finance') OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX bar_attendance_one_open ON public.bar_staff_attendance(club_id,staff_id) WHERE ended_at IS NULL;
ALTER TABLE public.bar_tips ADD COLUMN work_shift_id uuid REFERENCES public.bar_work_shifts(id);
CREATE TABLE public.bar_shift_tip_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES public.clubs(id),tip_id uuid NOT NULL REFERENCES public.bar_tips(id),staff_id uuid NOT NULL REFERENCES public.bar_counter_devices(id),staff_name text NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>=0),hours numeric NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tip_id,staff_id));
GRANT SELECT ON public.bar_shift_tip_allocations TO authenticated; GRANT ALL ON public.bar_shift_tip_allocations TO service_role;
ALTER TABLE public.bar_shift_tip_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_allocation_read ON public.bar_shift_tip_allocations FOR SELECT TO authenticated USING(public.is_club_admin_or_permitted(auth.uid(),club_id,'bar') OR public.has_club_permission(auth.uid(),club_id,'finance') OR public.has_role(auth.uid(),'admin'));
CREATE VIEW public.bar_staff_tip_earnings WITH (security_invoker=true) AS SELECT t.id,t.club_id,t.staff_id,t.staff_name,t.amount,t.status,t.created_at,t.earned_at FROM public.bar_tips t WHERE t.work_shift_id IS NULL UNION ALL SELECT a.id,a.club_id,a.staff_id,a.staff_name,a.amount,t.status,a.created_at,t.earned_at FROM public.bar_shift_tip_allocations a JOIN public.bar_tips t ON t.id=a.tip_id;
GRANT SELECT ON public.bar_staff_tip_earnings TO authenticated,service_role;
CREATE FUNCTION public._bar_staff_hours(_club uuid,_staff uuid,_from timestamptz,_to timestamptz) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(sum(greatest(extract(epoch FROM (least(ended_at,_to)-greatest(paid_start,_from))),0)/3600),0) FROM bar_staff_attendance WHERE club_id=_club AND staff_id=_staff AND ended_at IS NOT NULL AND ended_at>_from AND paid_start<_to $$;
REVOKE ALL ON FUNCTION public._bar_staff_hours(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._bar_allocate_shift_tip(_tip uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_tips; total_hours numeric; cents bigint; p record; share numeric; BEGIN
 SELECT * INTO t FROM bar_tips WHERE id=_tip FOR UPDATE;
 IF t.work_shift_id IS NULL OR t.status<>'earned' OR EXISTS(SELECT 1 FROM bar_shift_tip_allocations WHERE tip_id=t.id) OR NOT EXISTS(SELECT 1 FROM bar_work_shifts WHERE id=t.work_shift_id AND closed_at IS NOT NULL) THEN RETURN; END IF;
 SELECT sum(greatest(extract(epoch FROM(a.ended_at-a.paid_start)),0)/3600) INTO total_hours FROM bar_staff_attendance a WHERE a.shift_id=t.work_shift_id;
 IF coalesce(total_hours,0)=0 THEN RETURN; END IF; cents:=round(t.amount*100);
 FOR p IN WITH h AS (SELECT a.staff_id,sum(greatest(extract(epoch FROM(a.ended_at-a.paid_start)),0)/3600) hours FROM bar_staff_attendance a WHERE a.shift_id=t.work_shift_id GROUP BY a.staff_id), q AS (SELECT *,floor(cents*hours/total_hours) base,mod(cents*hours/total_hours,1) rem FROM h WHERE hours>0) SELECT q.*,d.label,row_number() OVER(ORDER BY q.rem DESC,q.staff_id) rn,sum(q.base) OVER() base_total FROM q JOIN bar_counter_devices d ON d.id=q.staff_id ORDER BY q.staff_id LOOP
 share:=(p.base+CASE WHEN p.rn<=cents-p.base_total THEN 1 ELSE 0 END)/100;
 INSERT INTO bar_shift_tip_allocations(club_id,tip_id,staff_id,staff_name,amount,hours) VALUES(t.club_id,t.id,p.staff_id,p.label,share,p.hours);
 IF share>0 THEN INSERT INTO club_journal_entries(club_id,journal_ref,account,debit,credit,description) VALUES(t.club_id,t.id,'bar_income',share,0,'Tip income — Shared shift'),(t.club_id,t.id,'bar_income',0,share,'Tip income — '||p.label); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public._bar_allocate_shift_tip(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._bar_track_shared_tip() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='INSERT' THEN SELECT s.id INTO NEW.work_shift_id FROM bar_work_shifts s WHERE s.club_id=NEW.club_id AND s.closed_at IS NULL AND s.split_tips AND EXISTS(SELECT 1 FROM bar_staff_attendance a WHERE a.shift_id=s.id AND a.staff_id=NEW.staff_id AND a.ended_at IS NULL); RETURN NEW; END IF;
 IF NEW.work_shift_id IS NOT NULL AND NEW.status='earned' AND OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO club_journal_entries(club_id,journal_ref,account,debit,credit,description) VALUES(NEW.club_id,NEW.id,'bar_income',NEW.amount,0,'Tip income — '||NEW.staff_name),(NEW.club_id,NEW.id,'bar_income',0,NEW.amount,'Tip income — Shared shift'); PERFORM _bar_allocate_shift_tip(NEW.id); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public._bar_track_shared_tip() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bar_tip_shift_stamp BEFORE INSERT ON public.bar_tips FOR EACH ROW EXECUTE FUNCTION public._bar_track_shared_tip();
CREATE TRIGGER bar_tip_shift_earned AFTER UPDATE OF status ON public.bar_tips FOR EACH ROW EXECUTE FUNCTION public._bar_track_shared_tip();
CREATE FUNCTION public.bar_counter_shift_status(_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s bar_counter_sessions; BEGIN SELECT * INTO s FROM bar_counter_sessions WHERE token=_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personal counter PIN required'; END IF; PERFORM _bar_tip_authorise(s.club_id,_token); RETURN jsonb_build_object('club_id',s.club_id,'opening',coalesce((SELECT staff_normal_opening::text FROM club_bar_settings WHERE club_id=s.club_id),'16:00:00'),'attendance',(SELECT to_jsonb(a) FROM bar_staff_attendance a WHERE a.session_id=s.id AND a.ended_at IS NULL LIMIT 1),'shift',(SELECT to_jsonb(w) FROM bar_work_shifts w WHERE w.club_id=s.club_id AND w.closed_at IS NULL)); END $$;
REVOKE ALL ON FUNCTION public.bar_counter_shift_status(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bar_counter_shift_status(uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_counter_start_shift(_token uuid,_kind text,_start timestamptz DEFAULT NULL,_split boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s bar_counter_sessions;w bar_work_shifts;a bar_staff_attendance;opening time;paid timestamptz; BEGIN
 SELECT * INTO s FROM bar_counter_sessions WHERE token=_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personal counter PIN required'; END IF; PERFORM _bar_tip_authorise(s.club_id,_token); PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||s.club_id));
 IF _kind NOT IN ('normal','special') OR _kind IS NULL OR (_split AND _kind<>'special') THEN RAISE EXCEPTION 'Invalid shift type'; END IF;
 SELECT * INTO a FROM bar_staff_attendance WHERE club_id=s.club_id AND staff_id=s.device_id AND ended_at IS NULL FOR UPDATE;
 IF FOUND THEN IF a.session_id<>s.id THEN RAISE EXCEPTION 'This person already has an open shift; end or correct it first'; END IF; RETURN to_jsonb(a); END IF;
 SELECT * INTO w FROM bar_work_shifts WHERE club_id=s.club_id AND closed_at IS NULL FOR UPDATE;
 IF FOUND AND (w.kind<>_kind OR w.split_tips<>coalesce(_split,false)) THEN RAISE EXCEPTION 'Join the current shift using its existing type and tip-sharing setting'; END IF;
 IF _kind='special' THEN IF _start IS NULL OR _start<now()-interval '1 minute' OR _start>now()+interval '24 hours' THEN RAISE EXCEPTION 'Choose a start from now onward; earlier attendance needs management correction'; END IF; paid:=greatest(_start,now()); ELSE SELECT staff_normal_opening INTO opening FROM club_bar_settings WHERE club_id=s.club_id; paid:=greatest(now(),(((now() AT TIME ZONE 'Africa/Johannesburg')::date+coalesce(opening,'16:00'::time)) AT TIME ZONE 'Africa/Johannesburg')); END IF;
 IF w.id IS NULL THEN INSERT INTO bar_work_shifts(club_id,kind,split_tips) VALUES(s.club_id,_kind,coalesce(_split,false)) RETURNING * INTO w; END IF;
 INSERT INTO bar_staff_attendance(club_id,shift_id,staff_id,session_id,paid_start) VALUES(s.club_id,w.id,s.device_id,s.id,paid) RETURNING * INTO a; RETURN to_jsonb(a); END $$;
REVOKE ALL ON FUNCTION public.bar_counter_start_shift(uuid,text,timestamptz,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bar_counter_start_shift(uuid,text,timestamptz,boolean) TO anon,authenticated;
CREATE FUNCTION public.bar_counter_end_shift(_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s bar_counter_sessions; BEGIN SELECT * INTO s FROM bar_counter_sessions WHERE token=_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personal counter PIN required'; END IF; PERFORM _bar_tip_authorise(s.club_id,_token); PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||s.club_id)); UPDATE bar_staff_attendance SET ended_at=now(),end_reason='exit' WHERE session_id=s.id AND ended_at IS NULL; UPDATE bar_counter_sessions SET revoked_at=now() WHERE id=s.id; END $$;
REVOKE ALL ON FUNCTION public.bar_counter_end_shift(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bar_counter_end_shift(uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_close_work_shift(_club_id uuid,_token uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w bar_work_shifts;t record; BEGIN PERFORM _bar_tip_authorise(_club_id,_token); PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||_club_id)); SELECT * INTO w FROM bar_work_shifts WHERE club_id=_club_id AND closed_at IS NULL FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; UPDATE bar_staff_attendance SET ended_at=now(),end_reason='cash_up' WHERE shift_id=w.id AND ended_at IS NULL; UPDATE bar_work_shifts SET closed_at=now() WHERE id=w.id; FOR t IN SELECT id FROM bar_tips WHERE work_shift_id=w.id AND status='earned' ORDER BY id LOOP PERFORM _bar_allocate_shift_tip(t.id); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.bar_close_work_shift(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bar_close_work_shift(uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_set_normal_shift_opening(_club_id uuid,_time time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM _bar_tip_authorise(_club_id,NULL); IF _time IS NULL THEN RAISE EXCEPTION 'Opening time required'; END IF; UPDATE club_bar_settings SET staff_normal_opening=_time WHERE club_id=_club_id; END $$;
REVOKE ALL ON FUNCTION public.bar_set_normal_shift_opening(uuid,time) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bar_set_normal_shift_opening(uuid,time) TO authenticated;
CREATE FUNCTION public.bar_staff_attendance_log(_club_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM _bar_tip_authorise(_club_id,NULL); RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'staff_id',a.staff_id,'name',d.label,'kind',w.kind,'start',a.paid_start,'end',a.ended_at,'hours',CASE WHEN a.ended_at IS NOT NULL THEN greatest(extract(epoch FROM(a.ended_at-a.paid_start)),0)/3600 END,'split_tips',w.split_tips,'reason',a.correction_reason) ORDER BY a.paid_start DESC) FROM bar_staff_attendance a JOIN bar_counter_devices d ON d.id=a.staff_id JOIN bar_work_shifts w ON w.id=a.shift_id WHERE a.club_id=_club_id AND (a.ended_at IS NULL OR a.ended_at>_bar_payroll_since(_club_id))),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.bar_staff_attendance_log(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bar_staff_attendance_log(uuid) TO authenticated;
CREATE FUNCTION public.bar_correct_staff_attendance(_id uuid,_start timestamptz,_end timestamptz,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a bar_staff_attendance; BEGIN SELECT * INTO a FROM bar_staff_attendance WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Attendance not found'; END IF; PERFORM _bar_tip_authorise(a.club_id,NULL); PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||a.club_id)); IF nullif(btrim(_reason),'') IS NULL OR _start IS NULL OR _end IS NULL OR _end<_start OR _end>now() THEN RAISE EXCEPTION 'Valid times and correction reason required'; END IF; IF EXISTS(SELECT 1 FROM bar_shift_tip_allocations x JOIN bar_tips t ON t.id=x.tip_id WHERE t.work_shift_id=a.shift_id) OR EXISTS(SELECT 1 FROM bar_payroll_runs r WHERE r.club_id=a.club_id AND r.status='confirmed' AND coalesce(r.attendance_cutoff,r.confirmed_at)>=a.paid_start) THEN RAISE EXCEPTION 'Attendance already allocated or paid; preserve the saved record'; END IF; IF EXISTS(SELECT 1 FROM bar_staff_attendance b WHERE b.club_id=a.club_id AND b.staff_id=a.staff_id AND b.id<>a.id AND tstzrange(b.paid_start,greatest(b.paid_start,coalesce(b.ended_at,'infinity'::timestamptz)),'[)') && tstzrange(_start,_end,'[)')) THEN RAISE EXCEPTION 'Overlapping attendance'; END IF; UPDATE bar_staff_attendance SET corrections=corrections||jsonb_build_array(jsonb_build_object('before_start',a.paid_start,'before_end',a.ended_at,'after_start',_start,'after_end',_end,'reason',_reason,'by',auth.uid(),'at',now())),paid_start=_start,ended_at=_end,end_reason='management',correction_reason=_reason,corrected_by=auth.uid() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.bar_correct_staff_attendance(uuid,timestamptz,timestamptz,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bar_correct_staff_attendance(uuid,timestamptz,timestamptz,text) TO authenticated;
DO $ddl$ DECLARE p record;def text; BEGIN FOR p IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('bar_staff_tip_balances','bar_pay_staff_tips','bar_confirm_payroll_run','bar_cash_up_edit_staff','bar_cash_up_edit_payouts','bar_cash_up_admin_correct','bar_staff_pay_overview','_bar_prepare_payroll_runs') LOOP def:=pg_get_functiondef(p.oid); def:=replace(def,'FROM bar_tips','FROM bar_staff_tip_earnings'); EXECUTE def; END LOOP; END $ddl$;
CREATE OR REPLACE FUNCTION public.bar_set_staff_pay(_club_id uuid,_staff_id uuid,_basis text,_amount numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM _bar_tip_authorise(_club_id,NULL); IF _basis IS NULL OR _basis NOT IN ('monthly','shift','hourly') THEN RAISE EXCEPTION 'Invalid pay basis'; END IF; IF _amount IS NULL OR _amount<0 OR _amount::text IN ('NaN','Infinity','-Infinity') OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Invalid amount'; END IF; IF NOT EXISTS(SELECT 1 FROM bar_counter_devices WHERE id=_staff_id AND club_id=_club_id) THEN RAISE EXCEPTION 'Staff not found'; END IF; INSERT INTO bar_staff_salaries(club_id,staff_id,pay_basis,monthly_salary,shift_rate,hourly_rate) VALUES(_club_id,_staff_id,_basis,CASE WHEN _basis='monthly' THEN _amount ELSE 0 END,CASE WHEN _basis='shift' THEN _amount ELSE 0 END,CASE WHEN _basis='hourly' THEN _amount ELSE 0 END) ON CONFLICT(club_id,staff_id) DO UPDATE SET pay_basis=_basis,monthly_salary=CASE WHEN _basis='monthly' THEN _amount ELSE bar_staff_salaries.monthly_salary END,shift_rate=CASE WHEN _basis='shift' THEN _amount ELSE bar_staff_salaries.shift_rate END,hourly_rate=CASE WHEN _basis='hourly' THEN _amount ELSE bar_staff_salaries.hourly_rate END,updated_at=now(); END $$;
DO $ddl$ DECLARE def text; BEGIN
 SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='_bar_prepare_payroll_runs';
 def:=replace(def,'extract(day FROM v_today)=least(cbs.staff_payday,v_last_day)','extract(day FROM v_today)>=least(cbs.staff_payday,v_last_day)');
 def:=replace(def,'v_since:=public._bar_payroll_since(s.club_id);','IF EXISTS(SELECT 1 FROM bar_staff_attendance WHERE club_id=s.club_id AND ended_at IS NULL) THEN CONTINUE; END IF; v_since:=public._bar_payroll_since(s.club_id);');
 def:=replace(def,'INSERT INTO bar_payroll_runs(club_id,period) VALUES(s.club_id,v_period)','INSERT INTO bar_payroll_runs(club_id,period,attendance_cutoff) VALUES(s.club_id,v_period,now())');
 def:=replace(def,'shifts_from,calculated_salary)','shifts_from,calculated_salary,hours,hourly_rate)');
 def:=replace(def,'x.rate,v_since,x.pay FROM','x.rate,v_since,x.pay,x.hours,x.hourly_rate FROM');
 def:=replace(def,$txt$CASE WHEN sal.pay_basis='shift' THEN round$txt$,$txt$public._bar_staff_hours(d.club_id,d.id,v_since,now()) hours, sal.hourly_rate, CASE WHEN sal.pay_basis='hourly' THEN round(sal.hourly_rate*public._bar_staff_hours(d.club_id,d.id,v_since,now()),2) WHEN sal.pay_basis='shift' THEN round$txt$);
 def:=replace(def,$txt$(x.basis='shift' AND coalesce(x.rate,0)>0)$txt$,$txt$(x.basis='shift' AND coalesce(x.rate,0)>0) OR (x.basis='hourly' AND coalesce(x.hourly_rate,0)>0)$txt$); EXECUTE def;
 SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bar_confirm_payroll_run'; def:=replace(def,$txt$IF run.status='confirmed' THEN RETURN; END IF;$txt$,$txt$IF run.status='confirmed' THEN RETURN; END IF; PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||run.club_id)); IF EXISTS(SELECT 1 FROM bar_staff_attendance WHERE club_id=run.club_id AND ended_at IS NULL AND paid_start<coalesce(run.attendance_cutoff,run.created_at)) THEN RAISE EXCEPTION 'Close unfinished attendance before confirming payroll'; END IF;$txt$); EXECUTE def;
 SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bar_staff_pay_overview';
 def:=replace(def,$txt$'shifts_since',v_since$txt$,$txt$'shifts_since',v_since,'opening',s.staff_normal_opening$txt$);
 def:=replace(def,$txt$'shift_rate',coalesce(sal.shift_rate,0)$txt$,$txt$'shift_rate',coalesce(sal.shift_rate,0),'hourly_rate',coalesce(sal.hourly_rate,0),'hours',public._bar_staff_hours(_club_id,d.id,v_since,now())$txt$);
 def:=replace(def,$txt$'pay_basis',l.pay_basis$txt$,$txt$'hours',l.hours,'hourly_rate',l.hourly_rate,'pay_basis',l.pay_basis$txt$); EXECUTE def; END $ddl$;
CREATE OR REPLACE FUNCTION public._bar_payroll_since(_club_id uuid) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT max(coalesce(r.attendance_cutoff,r.confirmed_at)) FROM bar_payroll_runs r WHERE r.club_id=_club_id AND r.status='confirmed'),now()-interval '1 month') $$;
DO $ddl$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bar_cash_up_close_v2'; def:=replace(def,'-- Tips handed over in cash','PERFORM public.bar_close_work_shift(_club_id,_token); -- Tips handed over in cash'); EXECUTE def; END $ddl$;
CREATE OR REPLACE FUNCTION public._bar_staff_shift_count(_club_id uuid,_staff_id uuid,_from timestamptz,_to timestamptz) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (SELECT count(*) FROM bar_staff_attendance a WHERE a.club_id=_club_id AND a.staff_id=_staff_id AND a.ended_at IS NOT NULL AND a.ended_at>greatest(a.paid_start,_from) AND a.paid_start<_to)+(SELECT count(DISTINCT(s.created_at AT TIME ZONE 'Africa/Johannesburg')::date) FROM bar_counter_sessions s WHERE s.club_id=_club_id AND s.device_id=_staff_id AND s.created_at>=_from AND s.created_at<_to AND NOT EXISTS(SELECT 1 FROM bar_staff_attendance a WHERE a.session_id=s.id))::integer $$;
CREATE FUNCTION public._bar_staff_payout_lock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE available numeric; BEGIN PERFORM pg_advisory_xact_lock(hashtext('bar_cash_up:'||NEW.club_id)); PERFORM 1 FROM bar_counter_devices WHERE id=NEW.staff_id AND club_id=NEW.club_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Staff not found'; END IF; SELECT coalesce((SELECT sum(amount) FROM bar_staff_tip_earnings WHERE club_id=NEW.club_id AND staff_id=NEW.staff_id AND status='earned'),0)-coalesce((SELECT sum(amount) FROM bar_tip_payouts WHERE club_id=NEW.club_id AND staff_id=NEW.staff_id AND id<>NEW.id),0) INTO available; IF NEW.amount>available THEN RAISE EXCEPTION 'Payout exceeds allocated unpaid tips'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public._bar_staff_payout_lock() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bar_payout_allocated_guard BEFORE INSERT OR UPDATE OF amount ON public.bar_tip_payouts FOR EACH ROW EXECUTE FUNCTION public._bar_staff_payout_lock();